// ===========================================================================
// Фикстура golden-сцен блендинга (§40.2, tests/agent/blend_golden_test.py).
//
// Одна сцена, одна геометрия, один меняющийся параметр — режим смешивания
// накладки. Поэтому разница между кадрами объясняется ТОЛЬКО режимом, а
// эталон каждого режима сравнивается с живым кадром по числу различающихся
// пикселей.
//
// Числа (тест берёт их из $.fixture.colors()/geometry(), а не из головы):
//   * кадр 320x240, камера в (160,120), зум 1 — мир совпадает с экраном;
//   * фон мира      #14202c (20,32,44)  — виден по углам;
//   * подложка      #406080 (64,96,128) — 240x160 в центре, непрозрачная;
//   * накладка      #C0A05080 (192,160,80), альфа 128 — 120x80 в центре.
//
// Точки замера теста: центр накладки (160,120), подложка вне накладки
// (60,120), фон вне подложки (10,10). Накладка полупрозрачная нарочно: в
// режиме none (запись без смешивания) кадр обязан отличаться от alpha, иначе
// «режим не поддержан» выглядело бы как совпадение.
//
// Перегенерация эталонов: см. шапку tests/agent/blend_golden_test.py.
// ===========================================================================
$.ready(() => {
    $.world.gravity(0, 0).color('#14202c');
    $.camera.at(160, 120).zoom(1);

    $('<rect>', { id: 'back' }).at(160, 120).size(240, 160)
        .color('#406080').appendTo($.world);

    // Накладка: её режим и есть предмет проверки. По умолчанию alpha —
    // ровно то, что движок делает без явного .blend().
    $('<rect>', { id: 'overlay' }).at(160, 120).size(120, 80)
        .color('#C0A05080').blend('alpha').appendTo($.world);

    $.fixture = {
        /** Сменить режим накладки; вернуть ДЕЙСТВУЮЩИЙ режим (после отката). */
        mode(name) {
            $('#overlay').blend(name);
            return $('#overlay').blend();
        },

        /** Текущий режим накладки. */
        current() { return $('#overlay').blend(); },

        /** Цвета сцены — тест считает ожидание из них, а не из своих констант. */
        colors() {
            return {
                bg: [20, 32, 44],          // #14202c, фон мира
                back: [64, 96, 128],       // #406080, подложка
                over: [192, 160, 80],      // #C0A05080, накладка (RGB)
                over_alpha: 128,           // её альфа 0..255
            };
        },

        /** Геометрия в ЛОГИЧЕСКИХ координатах кадра (мир == экран). */
        geometry() {
            return {
                size: { w: 320, h: 240 },
                overlay: { x: 160, y: 120, w: 120, h: 80 },
                back: { x: 160, y: 120, w: 240, h: 160 },
                // Точки замера: центр накладки, подложка вне накладки, фон.
                probe_over: { x: 160, y: 120 },
                probe_back: { x: 60, y: 120 },
                probe_bg: { x: 10, y: 10 },
            };
        },
    };
});
